use std::io

fn del(keys: Vec<int>, left: Vec<int>, right: Vec<int>, n: int, x: int) -> int {
    if n < 0 {
        return n
    }
    let i = n as usize
    if x < keys[i] {
        let l = left[i]
        let r = del(keys, left, right, l, x)
        left[i] = r
        return n
    }
    if x > keys[i] {
        let rr = right[i]
        let r = del(keys, left, right, rr, x)
        right[i] = r
        return n
    }
    if left[i] < 0 {
        return right[i]
    }
    if right[i] < 0 {
        return left[i]
    }
    let mut s = right[i]
    while left[s as usize] >= 0 {
        s = left[s as usize]
    }
    let sk = keys[s as usize]
    keys[i] = sk
    let rr = right[i]
    let r = del(keys, left, right, rr, sk)
    right[i] = r
    n
}

fn height(left: Vec<int>, right: Vec<int>, n: int) -> int {
    if n < 0 {
        return 0
    }
    let a = height(left, right, left[n as usize])
    let b = height(left, right, right[n as usize])
    if a > b {
        return a + 1
    }
    b + 1
}

fn walk(keys: Vec<int>, left: Vec<int>, right: Vec<int>, n: int, out: Vec<string>) {
    if n < 0 {
        return
    }
    walk(keys, left, right, left[n as usize], out)
    out.push(keys[n as usize].to_string())
    walk(keys, left, right, right[n as usize], out)
}

fn main() {
    let mut keys: Vec<int> = Vec::new()
    let mut left: Vec<int> = Vec::new()
    let mut right: Vec<int> = Vec::new()
    let mut root: int = -1
    loop {
        let line = match io::read_line() {
            Ok(s) => s,
            Err(_) => break,
        }
        if line.len() == 0 {
            break
        }
        let parts: Vec<string> = line.trim().split(" ").collect()
        let cmd = parts[0]
        if cmd == "" {
            continue
        }
        let mut x: int = 0
        if parts.len() > 1 {
            x = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            if root < 0 {
                keys.push(x)
                left.push(-1)
                right.push(-1)
                root = 0
                println("ok")
            } else {
                let mut cur = root
                let mut done = false
                while !done {
                    let c = cur as usize
                    if x == keys[c] {
                        println("dup")
                        done = true
                    } else if x < keys[c] {
                        if left[c] < 0 {
                            left[c] = keys.len() as int
                            keys.push(x)
                            left.push(-1)
                            right.push(-1)
                            println("ok")
                            done = true
                        } else {
                            cur = left[c]
                        }
                    } else {
                        if right[c] < 0 {
                            right[c] = keys.len() as int
                            keys.push(x)
                            left.push(-1)
                            right.push(-1)
                            println("ok")
                            done = true
                        } else {
                            cur = right[c]
                        }
                    }
                }
            }
        } else if cmd == "contains" || cmd == "delete" {
            let mut cur = root
            let mut found = false
            while cur >= 0 && !found {
                let c = cur as usize
                if x == keys[c] {
                    found = true
                } else if x < keys[c] {
                    cur = left[c]
                } else {
                    cur = right[c]
                }
            }
            if cmd == "contains" {
                if found {
                    println("yes")
                } else {
                    println("no")
                }
            } else if found {
                root = del(keys, left, right, root, x)
                println("ok")
            } else {
                println("missing")
            }
        } else if cmd == "inorder" {
            let mut out: Vec<string> = Vec::new()
            walk(keys, left, right, root, out)
            if out.len() == 0 {
                println("<empty>")
            } else {
                println(out.join(" "))
            }
        } else if cmd == "height" {
            println(height(left, right, root).to_string())
        } else if cmd == "min" || cmd == "max" {
            if root < 0 {
                println("empty")
            } else {
                let mut cur = root
                if cmd == "min" {
                    while left[cur as usize] >= 0 {
                        cur = left[cur as usize]
                    }
                } else {
                    while right[cur as usize] >= 0 {
                        cur = right[cur as usize]
                    }
                }
                println(keys[cur as usize].to_string())
            }
        }
    }
}

